  "🔱 Durga Puja": "🔱 Durga Puja",
  "Durga Puja": "Durga Puja",
  "Happy Durga Puja": "Feliz Durga Puja",
  "May Maa Durga bless you with strength, joy and prosperity. Shubho Durga Puja!": "Que Maa Durga te bendiga con fuerza, alegría y prosperidad. ¡Shubho Durga Puja!",
