  "Out of every sky I've seen, you're still the brightest light in mine.": "De todos los cielos que he visto, tú sigues siendo la luz más brillante del mío.",
  "I love that home stopped being a place the day it became you.": "Me encanta que el hogar dejó de ser un lugar el día que se convirtió en ti.",
  "Every firework fades. What I feel for you only gets louder.": "Todo fuego artificial se apaga. Lo que siento por ti solo suena más fuerte.",
  "I'd choose you on every Diwali, in every lifetime.": "Te elegiría en cada Diwali, en cada vida.",
  "You're the reason ordinary nights feel like festivals.": "Eres la razón por la que las noches normales parecen fiestas.",
  "I love you because with you, even silence feels like…": "Te quiero porque contigo, hasta el silencio se siente como…",
  "Warning: you make my heart burst louder than a thousand-wala.": "Aviso: haces que mi corazón estalle más fuerte que una traca de mil.",
  "Are you a sparkler? You light me up every time you smile.": "¿Eres una bengala? Me iluminas cada vez que sonríes.",
  "I lost my words the first time you smiled. Still looking for them.": "Me quedé sin palabras la primera vez que sonreíste. Todavía las busco.",
  "You, me and a rooftop full of fireworks. Say yes?": "Tú, yo y una azotea llena de fuegos artificiales. ¿Dices que sí?",
  "My favourite view tonight isn't the fireworks. It's you.": "Mi vista favorita esta noche no son los fuegos artificiales. Eres tú.",
  "The first thing I noticed about you was…": "Lo primero que noté de ti fue…",
  "You make my bad days shorter and my good days shine.": "Haces mis días malos más cortos y mis días buenos más brillantes.",
  "I love the way you laugh before you finish your own jokes.": "Me encanta cómo te ríes antes de terminar tus propios chistes.",
  "Thank you for being my safe place in a noisy world.": "Gracias por ser mi lugar seguro en un mundo ruidoso.",
  "Your hug is my favourite place to be.": "Tu abrazo es mi lugar favorito.",
  "With you, every day is a little Diwali.": "Contigo, cada día es un pequeño Diwali.",
  "I love the little things you do, like…": "Me encantan los pequeños detalles que haces, como…",
  "I love you more than free gems. And that's a lot.": "Te quiero más que a las gemas gratis. Y eso es mucho.",
  "You're my favourite notification.": "Eres mi notificación favorita.",
  "I love you even when you steal the last laddoo.": "Te quiero incluso cuando te robas el último laddoo.",
  "You're the only one I'd share my phuljhari with.": "Eres la única persona con quien compartiría mi bengala.",
  "Life with you is like a cracker: loud, bright and a little dangerous.": "La vida contigo es como un petardo: ruidosa, brillante y un poco peligrosa.",
  "I love you because you laugh at my worst jokes, like…": "Te quiero porque te ríes de mis peores chistes, como…",
  "Amma, every light in my life started with you.": "Mamá, cada luz de mi vida empezó contigo.",
  "Thank you for believing in me before I believed in myself.": "Gracias por creer en mí antes de que yo creyera en mí.",
  "You gave me roots, and then you gave me wings.": "Me diste raíces, y luego me diste alas.",
  "Friends like you make every festival feel like home.": "Los amigos como tú hacen que cada fiesta se sienta como en casa.",
  "Whatever I become, it began with your love.": "Lo que sea que llegue a ser, empezó con tu amor.",
  "I'm grateful for you because…": "Te estoy agradecido porque…",
  "Reasons to love": "Motivos para amar",
