  "The Silver Peacock Lamp": "La lámpara del pavo real de plata",
  "Thieves took the temple’s silver peacock lamp. Follow the jasmine trail and bring it back": "Unos ladrones se llevaron la lámpara del pavo real de plata del templo. Sigue el rastro de jazmín y tráela de vuelta",
  "Lamps for Madurai": "Lámparas para Madurai",
  "Madurai’s temple street is full of lamps tonight, and the silver peacock lamp is the brightest.": "La calle del templo de Madurai está llena de lámparas esta noche, y la lámpara del pavo real de plata es la más brillante.",
  "The peacock lamp is gone!": "¡La lámpara del pavo real desapareció!",
  "Thieves have taken the silver peacock lamp and slipped into the flower market.": "Unos ladrones se llevaron la lámpara del pavo real de plata y se escabulleron por el mercado de flores.",
  "Follow the jasmine": "Sigue el jazmín",
  "Light crackers to see in the dark. Follow the clues: jasmine petals, an anklet bell, a flower basket.": "Enciende petardos para ver en la oscuridad. Sigue las pistas: pétalos de jazmín, un cascabel de tobillera, una canasta de flores.",
  "Bring it back": "Tráela de vuelta",
  "Find the peacock lamp and carry it back to the temple steps before the lamps are lit.": "Encuentra la lámpara del pavo real y llévala a las escaleras del templo antes de que enciendan las lámparas.",
  "🦚 The silver peacock lamp is gone! Light a cracker by the dark patch to find the jasmine trail": "🦚 ¡La lámpara del pavo real de plata desapareció! Enciende un petardo junto a la zona oscura para encontrar el rastro de jazmín",
  "🚨 Seth-ji thinks YOU are the thief! Run the peacock lamp to the temple steps 🛕": "🚨 ¡Seth-ji cree que TÚ eres el ladrón! Lleva la lámpara del pavo real corriendo a las escaleras del templo 🛕",
  "The peacock lamp is home!": "¡La lámpara del pavo real está en casa!",
  "The temple’s lamps shine on the silver peacock again 🪔": "Las lámparas del templo vuelven a brillar sobre el pavo real de plata 🪔",
  "You followed the jasmine petals, the anklet bell and the flower basket, and brought the silver peacock lamp back to the temple steps.": "Seguiste los pétalos de jazmín, el cascabel y la canasta de flores, y devolviste la lámpara del pavo real de plata a las escaleras del templo.",
  "I brought the silver peacock lamp home to the temple in Fireworks Street!": "¡Devolví la lámpara del pavo real de plata al templo en la Calle de Fuegos Artificiales!",
  "Light up the jasmine trail": "Ilumina el rastro de jazmín",
  "Jasmine petals! The thieves ran up the street with flowers on their feet": "¡Pétalos de jazmín! Los ladrones corrieron calle arriba con flores en los pies",
  "A silver anklet bell, dropped on the run. They went this way": "Un cascabel de tobillera de plata, caído en la huida. Fueron por aquí",
  "Search the flower basket": "Registra la canasta de flores",
  "Under the jasmine in a flower-seller’s basket: the silver peacock lamp!": "Bajo el jazmín, en la canasta de una florista: ¡la lámpara del pavo real de plata!",
  "The Golden Deepam Lamp": "La lámpara dorada del Deepam",
  "Thieves took the great lamp for the Deepam. Follow the oil drips and bring it back for the lighting": "Unos ladrones se llevaron la gran lámpara del Deepam. Sigue las gotas de aceite y tráela de vuelta para encenderla",
  "The great lamp": "La gran lámpara",
  "Tonight the great golden lamp is to be lit for Karthigai Deepam, for the whole town to see.": "Esta noche se encenderá la gran lámpara dorada de Karthigai Deepam, para que todo el pueblo la vea.",
  "The Deepam lamp is gone!": "¡La lámpara del Deepam desapareció!",
  "Thieves have taken the golden lamp, still dripping with oil, into the dark streets.": "Unos ladrones se llevaron la lámpara dorada, todavía goteando aceite, por las calles oscuras.",
  "Follow the oil": "Sigue el aceite",
  "Light crackers to see in the dark. Follow the clues: oil drips, a dropped bundle of wicks, the oil merchant’s cart.": "Enciende petardos para ver en la oscuridad. Sigue las pistas: gotas de aceite, un manojo de mechas caído, la carreta del vendedor de aceite.",
  "Light the Deepam": "Enciende el Deepam",
