  "🪔 The golden Deepam lamp is gone! Light a cracker by the dark patch to find the oil drips": "🪔 ¡La lámpara dorada del Deepam desapareció! Enciende un petardo junto a la zona oscura para encontrar las gotas de aceite",
  "🚨 Seth-ji thinks YOU are the thief! Run the Deepam lamp to the temple steps 🛕": "🚨 ¡Seth-ji cree que TÚ eres el ladrón! Lleva la lámpara del Deepam corriendo a las escaleras del templo 🛕",
