  "Next, your phone asks to let the app read your contacts and, if you like, your calendar: only the names, birthdays and photos of people with a birthday, and the birthdays in your Google Birthdays calendar. You pick who to add, and they stay on this phone. Not now keeps everything else working.": "A continuación, tu teléfono te pedirá permiso para que la app lea tus contactos y, si quieres, tu calendario: solo los nombres, cumpleaños y fotos de las personas con cumpleaños, y los cumpleaños de tu calendario de Google Birthdays. Tú eliges a quién añadir, y se quedan en este teléfono. Con Ahora no, todo lo demás sigue funcionando.",
